# paste-canvas

An infinite canvas for pasting and organizing images and notes.

## Packages

| Package | Description |
|---|---|
| `@paste-canvas/lib` | Core canvas library — framework-agnostic, storage-agnostic |
| `@paste-canvas/web` | Static web app using IndexedDB for persistence |
| `@paste-canvas/tauri` | Desktop app — folder-based workspace, file-system persistence |

## Getting started

```bash
bun install
bun run dev:web      # http://localhost:3000
bun run dev:tauri    # desktop app (requires Rust toolchain)
```

## Building

```bash
bun run build        # builds lib then web
bun run build:tauri  # builds lib then Tauri desktop app
```

## How it works

The library exposes a `PasteCanvas` class that mounts into any container element. Storage is handled by a `StorageAdapter` interface — swap implementations to change where data lives.

```ts
import { createCanvas } from '@paste-canvas/lib';

// Create and mount — data loads in the background:
createCanvas(document.body, myAdapter, { title: 'My Board' }).mount();

// Or keep a reference to destroy later:
const canvas = createCanvas(document.body, myAdapter).mount();
canvas.destroy(); // removes DOM and all event listeners
```

### Writing an adapter

Implement the `StorageAdapter` interface from `@paste-canvas/lib`:

```ts
import type { StorageAdapter, ItemData, TabData, EdgeData, ViewportState } from '@paste-canvas/lib';

class MyAdapter implements StorageAdapter {
  // Use a static factory if async setup is needed:
  // static async open(): Promise<MyAdapter> { ... }
  async putItem(item: ItemData): Promise<void> { ... }
  async deleteItem(id: number): Promise<void> { ... }
  async getAllItems(): Promise<ItemData[]> { ... }

  async putTab(tab: TabData): Promise<void> { ... }
  async deleteTab(id: number): Promise<void> { ... }
  async getAllTabs(): Promise<TabData[]> { ... }

  async putEdge(edge: EdgeData): Promise<void> { ... }
  async deleteEdge(id: number): Promise<void> { ... }
  async getAllEdges(): Promise<EdgeData[]> { ... }

  async saveViewport(tabId: number, state: ViewportState): Promise<void> { ... }
  async loadViewport(tabId: number): Promise<ViewportState | null> { ... }
  async saveActiveTab(tabId: number): Promise<void> { ... }
  async loadActiveTab(): Promise<number | null> { ... }
}
```

Images are stored as `ArrayBuffer` in `ItemData.imageData`. Your adapter receives already-encoded binary — no extra conversion needed.

### Keyboard shortcuts

| Key | Action |
|---|---|
| `Ctrl+V` | Paste image or text |
| `Ctrl+Z` / `Ctrl+Y` | Undo / redo |
| `Ctrl+A` | Select all |
| `Ctrl+D` | Duplicate selected |
| `Ctrl+C` | Copy selected item |
| `Delete` / `Backspace` | Delete selected |
| `Escape` | Deselect |
| Scroll | Zoom |
| Drag (canvas) | Pan |
| Shift/Ctrl + drag | Marquee select |

import { createCanvas } from '@paste-canvas/lib';
import type { StorageAdapter, ItemData, TabData, EdgeData, ViewportState, TabLayout } from '@paste-canvas/lib';

// ── In-memory adapter ────────────────────────────────────────────────────────

class MemoryAdapter implements StorageAdapter {
  private items     = new Map<number, ItemData>();
  private tabs      = new Map<number, TabData>();
  private edges     = new Map<number, EdgeData>();
  private viewports = new Map<string, ViewportState>();
  private activeTab: number | null = null;
  private tabLayout: TabLayout | null = null;

  async putItem(item: ItemData)    { this.items.set(item.id, item); }
  async deleteItem(id: number)     { this.items.delete(id); }
  async getAllItems()               { return [...this.items.values()]; }
  async getItemsForTab(tabId: number) { return [...this.items.values()].filter(item => item.tabId === tabId); }

  async putTab(tab: TabData)       { this.tabs.set(tab.id, tab); }
  async deleteTab(id: number)      { this.tabs.delete(id); }
  async getAllTabs()                { return [...this.tabs.values()]; }

  async putEdge(edge: EdgeData)    { this.edges.set(edge.id, edge); }
  async deleteEdge(id: number)     { this.edges.delete(id); }
  async getAllEdges()               { return [...this.edges.values()]; }
  async getEdgesForTab(tabId: number) { return [...this.edges.values()].filter(edge => edge.tabId === tabId); }

  async saveViewport(tabId: number, state: ViewportState) {
    this.viewports.set(`vp-${tabId}`, state);
  }
  async loadViewport(tabId: number) {
    return this.viewports.get(`vp-${tabId}`) ?? null;
  }
  async deleteViewport(tabId: number) { this.viewports.delete(`vp-${tabId}`); }
  async saveActiveTab(tabId: number) { this.activeTab = tabId; }
  async loadActiveTab()              { return this.activeTab; }
  async saveTabLayout(layout: TabLayout) { this.tabLayout = layout; }
  async loadTabLayout()                  { return this.tabLayout; }
}

// ── Image generation ─────────────────────────────────────────────────────────

function makeColorBlob(index: number): Promise<Blob> {
  return new Promise(resolve => {
    const cvs = document.createElement('canvas');
    cvs.width = 200; cvs.height = 150;
    const c = cvs.getContext('2d')!;
    const hue = (index * 137) % 360;
    c.fillStyle = `hsl(${hue}, 65%, 55%)`;
    c.fillRect(0, 0, 200, 150);
    c.fillStyle = 'rgba(255,255,255,0.9)';
    c.font = 'bold 22px sans-serif';
    c.textAlign = 'center';
    c.fillText(`#${index}`, 100, 82);
    cvs.toBlob(b => resolve(b!), 'image/png');
  });
}

// ── Layouts ───────────────────────────────────────────────────────────────────

type Layout = 'grid' | 'scatter';

function computePositions(count: number, layout: Layout): { x: number; y: number }[] {
  if (layout === 'grid') {
    const COLS  = Math.ceil(Math.sqrt(count));
    const GAP_X = 230, GAP_Y = 180;
    return Array.from({ length: count }, (_, i) => ({
      x: (i % COLS) * GAP_X,
      y: Math.floor(i / COLS) * GAP_Y,
    }));
  }
  // scatter: seeded pseudo-random, deterministic per count
  const spread = Math.ceil(Math.sqrt(count)) * 260;
  let seed = 42;
  const rand = () => { seed = (seed * 1664525 + 1013904223) & 0xffffffff; return (seed >>> 0) / 0xffffffff; };
  return Array.from({ length: count }, () => ({
    x: rand() * spread - spread / 2,
    y: rand() * spread - spread / 2,
  }));
}

// ── Seed adapter ─────────────────────────────────────────────────────────────

async function seedAdapter(adapter: MemoryAdapter, count: number): Promise<void> {
  await adapter.putTab({ id: 1, name: 'Stress Test', order: 0 });
  await adapter.saveActiveTab(1);

  const positions = computePositions(count, currentLayout);

  // Generate all blobs in parallel, then store
  const blobs = await Promise.all(
    Array.from({ length: count }, (_, i) => makeColorBlob(i + 1))
  );
  await Promise.all(blobs.map(async (blob, i) => {
    const buffer = await blob.arrayBuffer();
    await adapter.putItem({
      id: i + 1, type: 'img', tabId: 1,
      x: positions[i].x, y: positions[i].y,
      w: 200, h: 150, zIndex: i + 1,
      pluginData: { label: `#${i + 1}`, displayW: 200 },
      binaryData: { image: buffer },
      binaryKeys: ['image'],
    });
  }));
}

// ── Stats ─────────────────────────────────────────────────────────────────────

const elFps     = document.getElementById('stat-fps')!;
const elTotal   = document.getElementById('stat-total')!;
const elMounted = document.getElementById('stat-mounted')!;
const elLoad    = document.getElementById('stat-load')!;
const container = document.getElementById('canvas-root')!;

let currentTotal = 0;

function refreshStats() {
  elTotal.textContent   = String(currentTotal);
  elMounted.textContent = String(container.querySelectorAll('.item').length);
}

// FPS loop
const frameTimes: number[] = [];
let lastRafTime = performance.now();

function fpsLoop(now: number) {
  const delta = now - lastRafTime;
  lastRafTime = now;
  frameTimes.push(delta);
  if (frameTimes.length > 60) frameTimes.shift();
  const avg = frameTimes.reduce((a, b) => a + b, 0) / frameTimes.length;
  elFps.textContent = (1000 / avg).toFixed(1);
  refreshStats();
  requestAnimationFrame(fpsLoop);
}
requestAnimationFrame(fpsLoop);

// ── Canvas lifecycle ──────────────────────────────────────────────────────────

let currentLayout: Layout = 'scatter';
let activeCanvas: ReturnType<typeof createCanvas> | null = null;

async function runTest(count: number) {
  elLoad.textContent = '…';
  currentTotal = count;

  if (activeCanvas) {
    const parent = container.parentElement!;
    activeCanvas.destroy(); // removes container from DOM (it's the .paste-canvas-root)
    activeCanvas = null;
    parent.appendChild(container); // re-attach so getBoundingClientRect works
  }

  const adapter = new MemoryAdapter();
  const t0 = performance.now();
  await seedAdapter(adapter, count);

  activeCanvas = createCanvas(container, adapter, { title: `Stress Test (${count} items)` });
  // Use rAF to ensure container is laid out before mount triggers updateCulling
  requestAnimationFrame(() => {
    activeCanvas!.mount();
    requestAnimationFrame(() => {
      elLoad.textContent = (performance.now() - t0).toFixed(0) + ' ms';
      refreshStats();
    });
  });
}

// ── Wire controls ─────────────────────────────────────────────────────────────

let lastCount = 500;

document.querySelectorAll<HTMLButtonElement>('#controls button[data-count]').forEach(btn => {
  btn.addEventListener('click', () => { lastCount = Number(btn.dataset.count); void runTest(lastCount); });
});

const layoutToggle = document.getElementById('layout-toggle') as HTMLButtonElement;
layoutToggle.addEventListener('click', () => {
  currentLayout = currentLayout === 'scatter' ? 'grid' : 'scatter';
  layoutToggle.textContent = `Layout: ${currentLayout === 'scatter' ? 'Scatter' : 'Grid'}`;
  void runTest(lastCount);
});

void runTest(lastCount);

import { describe, expect, it, vi } from 'vitest';
import { ImagePlugin } from '../plugins/ImagePlugin.js';
import type { PluginAPI } from '../plugin.js';

function makeApi(itemEl: HTMLElement, overrides: Partial<PluginAPI> = {}): PluginAPI {
  return {
    itemId: 1,
    itemEl,
    signal: new AbortController().signal,
    scale: 0.2,
    isSelected: () => false,
    deselect: () => {},
    pushUndo: () => {},
    save: () => {},
    notifyResized: () => {},
    refreshOverview: () => {},
    toast: () => {},
    confirm: async () => false,
    ...overrides,
  };
}

describe('ImagePlugin overview refresh', () => {
  it('refreshes the zoomed-out overview tile when an image finishes decoding', () => {
    // Repro: a tab opened below OVERVIEW_SCALE draws the overview tile before images
    // decode (grey placeholders). When an image's load event fires, the plugin must
    // ask the core to rebuild the tile so the real image replaces the placeholder.
    const refreshOverview = vi.fn();
    const view = ImagePlugin.create(makeApi(document.createElement('div'), { refreshOverview }));

    view.img.dispatchEvent(new Event('load'));

    expect(refreshOverview).toHaveBeenCalled();
  });
});

