describe('GroupPlugin label', () => {
  it('deselects the group when the label gains focus, so the toolbar clears for typing', () => {
    const deselect = vi.fn();
    const view = GroupPlugin.create(makeApi({ deselect }));
    view.labelEl.dispatchEvent(new Event('focus'));
    expect(deselect).toHaveBeenCalled();
  });

  it('deselects again on a fresh click even when the label already holds focus', () => {
    // The group can be re-selected while the label keeps focus (the item drag
    // handler preventDefaults its pointerdown), so `focus` won't fire again — the
    // pointerdown must still clear the selection.
    const deselect = vi.fn();
    const view = GroupPlugin.create(makeApi({ deselect }));
    view.labelEl.dispatchEvent(new Event('pointerdown'));
    expect(deselect).toHaveBeenCalled();
  });
});

import { describe, it, expect, afterEach } from 'vitest';
import { css } from '../style.js';

describe('group title + selection toolbar CSS', () => {
  const appended: HTMLElement[] = [];
  afterEach(() => { for (const el of appended.splice(0)) el.remove(); });

  /** Inject the stylesheet and a fresh `.paste-canvas-root` to build into. */
  function root(): HTMLElement {
    const style = document.createElement('style');
    style.textContent = css;
    document.head.appendChild(style);
    const el = document.createElement('div');
    el.className = 'paste-canvas-root';
    document.body.appendChild(el);
    appended.push(style, el);
    return el;
  }

  it('renders the group label as a title above the box', () => {
    const group = document.createElement('div');
    group.className = 'item item-group';
    group.style.cssText = 'position:absolute;left:0;top:200px;width:400px;height:300px';
    const label = document.createElement('textarea');
    label.className = 'group-label';
    label.value = 'Title';
    group.appendChild(label);
    root().appendChild(group);

    // Label is a title above the box: its bottom edge is at or above the box top.
    expect(label.offsetTop + label.offsetHeight).toBeLessThanOrEqual(0);
  });

  it('shows an item toolbar only when the item is selected', () => {
    const item = document.createElement('div');
    item.className = 'item item-image';
    const tb = document.createElement('div');
    tb.className = 'item-toolbar';
    item.appendChild(tb);
    root().appendChild(item);

    expect(getComputedStyle(tb).pointerEvents).toBe('none'); // unselected: hidden

    item.classList.add('selected');
    expect(getComputedStyle(tb).pointerEvents).toBe('auto'); // selected: shown
  });

  it('hides item toolbars while a drag is in progress', () => {
    const item = document.createElement('div');
    item.className = 'item item-image selected';
    const tb = document.createElement('div');
    tb.className = 'item-toolbar';
    item.appendChild(tb);
    root().appendChild(item);

    expect(getComputedStyle(tb).pointerEvents).toBe('auto'); // selected: shown

    document.body.classList.add('paste-canvas-dragging');
    try {
      expect(getComputedStyle(tb).pointerEvents).toBe('none'); // dragging: hidden
    } finally {
      document.body.classList.remove('paste-canvas-dragging');
    }
  });
});

import { describe, expect, it } from 'vitest';
import { overviewItemSize } from '../canvas.js';
import type { ItemRecord } from '../types.js';

// Decode a real image of known dimensions so naturalWidth/naturalHeight are populated.
function loadImage(w: number, h: number): Promise<HTMLImageElement> {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const img = new Image();
  return new Promise((resolve, reject) => {
    img.onload  = () => resolve(img);
    img.onerror = () => reject(new Error('image failed to load'));
    img.src = c.toDataURL();
  });
}

function makeItem(opts: { type?: string; w?: number; h?: number; img?: HTMLImageElement }): ItemRecord {
  const el = document.createElement('div');
  if (opts.img) el.appendChild(opts.img);
  return {
    type: opts.type ?? 'img',
    w: opts.w ?? 0,
    h: opts.h ?? 0,
    el,
  } as unknown as ItemRecord;
}

describe('overviewItemSize', () => {
  it('derives a width-resize image height from its decoded aspect ratio when rec.h is 0', async () => {
    // The squish repro: a tall screenshot loaded straight into overview mode has h === 0.
    // 400×1200 source displayed at width 200 → height 600, not the old square-ish 200.
    const img = await loadImage(400, 1200);
    const { w, h } = overviewItemSize(makeItem({ w: 200, h: 0, img }));
    expect(w).toBe(200);
    expect(h).toBeCloseTo(600);
  });

  it('keeps wide images wide via aspect ratio', async () => {
    const img = await loadImage(800, 400);
    const { w, h } = overviewItemSize(makeItem({ w: 400, h: 0, img }));
    expect(w).toBe(400);
    expect(h).toBeCloseTo(200);
  });

  it('uses rec.h when it is known (mounted/measured items), ignoring aspect ratio', async () => {
    const img = await loadImage(400, 1200);
    const { h } = overviewItemSize(makeItem({ w: 200, h: 333, img }));
    expect(h).toBe(333);
  });

  it('falls back to 200 for an image whose bitmap has not decoded yet', () => {
    const img = new Image(); // no src → naturalWidth === 0
    const { w, h } = overviewItemSize(makeItem({ w: 200, h: 0, img }));
    expect(w).toBe(200);
    expect(h).toBe(200);
  });

  it('falls back to 200 for an image item with no <img> element', () => {
    const { h } = overviewItemSize(makeItem({ w: 200, h: 0 }));
    expect(h).toBe(200);
  });

  it('does not derive aspect ratio for non-image items', async () => {
    const img = await loadImage(400, 1200);
    const { h } = overviewItemSize(makeItem({ type: 'note', w: 200, h: 0, img }));
    expect(h).toBe(200);
  });

  it('defaults width to 200 when rec.w is 0, and scales height by aspect from that', async () => {
    const img = await loadImage(800, 400);
    const { w, h } = overviewItemSize(makeItem({ w: 0, h: 0, img }));
    expect(w).toBe(200);
    expect(h).toBeCloseTo(100);
  });
});

import { describe, expect, it } from 'vitest';
import { NotePlugin } from '../plugins/NotePlugin.js';
import type { PluginAPI } from '../plugin.js';

function makeApi(itemEl: HTMLElement): PluginAPI {
  return {
    itemId: 1,
    itemEl,
    signal: new AbortController().signal,
    scale: 1,
    isSelected: () => true,
    deselect: () => {},
    pushUndo: () => {},
    save: () => {},
    notifyResized: () => {},
    refreshOverview: () => {},
    toast: () => {},
    confirm: async () => false,
  };
}

describe('NotePlugin color shortcuts', () => {
  it('does not recolor a selected note when typing a color digit in a contentEditable field (e.g. tab title)', () => {
    const itemEl = document.createElement('div');
    const api = makeApi(itemEl);
    NotePlugin.create(api); // registers the document keydown listener

    const editable = document.createElement('span');
    editable.contentEditable = 'plaintext-only';
    document.body.append(itemEl, editable);

    try {
      // A color digit typed inside the editable must NOT recolor the note.
      editable.dispatchEvent(new KeyboardEvent('keydown', { key: '1', bubbles: true, cancelable: true }));
      expect(itemEl.classList.contains('colored')).toBe(false);

      // Control: the same key on a non-editable target still recolors.
      document.body.dispatchEvent(new KeyboardEvent('keydown', { key: '1', bubbles: true, cancelable: true }));
      expect(itemEl.classList.contains('colored')).toBe(true);
    } finally {
      itemEl.remove();
      editable.remove();
    }
  });
});

import { describe, it, expect } from 'vitest';
import { encodePcvs, decodePcvs, PcvsFormatError, exportCanvas, importCanvas } from '../export-import.js';
import type { StorageAdapter, ItemData, TabData, EdgeData, ViewportState } from '../types.js';

// ── Mock adapter ──────────────────────────────────────────────────────────────

function makeMockAdapter(initial?: {
  tabs?: TabData[];
  items?: ItemData[];
  edges?: EdgeData[];
  viewports?: Record<number, ViewportState>;
}): StorageAdapter & { _tabs: TabData[]; _items: ItemData[]; _edges: EdgeData[] } {
  const tabs:  TabData[]  = [...(initial?.tabs  ?? [])];
  const items: ItemData[] = [...(initial?.items ?? [])];
  const edges: EdgeData[] = [...(initial?.edges ?? [])];
  const viewports = new Map<number, ViewportState>(
    Object.entries(initial?.viewports ?? {}).map(([k, v]) => [Number(k), v])
  );
  return {
    _tabs: tabs, _items: items, _edges: edges,
    putTab:        async (t) => { const i = tabs.findIndex(x => x.id === t.id); i >= 0 ? tabs[i] = t : tabs.push(t); },
    deleteTab:     async (id) => { const i = tabs.findIndex(t => t.id === id); if (i >= 0) tabs.splice(i, 1); },
    getAllTabs:     async () => [...tabs],
    putItem:       async (item) => { const i = items.findIndex(x => x.id === item.id); i >= 0 ? items[i] = item : items.push(item); },
    deleteItem:    async (id) => { const i = items.findIndex(x => x.id === id); if (i >= 0) items.splice(i, 1); },
    getAllItems:    async () => [...items],
    getItemsForTab: async (tabId) => items.filter(item => item.tabId === tabId),
    putEdge:       async (e) => { const i = edges.findIndex(x => x.id === e.id); i >= 0 ? edges[i] = e : edges.push(e); },
    deleteEdge:    async (id) => { const i = edges.findIndex(x => x.id === id); if (i >= 0) edges.splice(i, 1); },
    getAllEdges:    async () => [...edges],
    getEdgesForTab: async (tabId) => edges.filter(edge => edge.tabId === tabId),
    saveViewport:  async (tabId, state) => { viewports.set(tabId, state); },
    loadViewport:  async (tabId) => viewports.get(tabId) ?? null,
    deleteViewport: async (tabId) => { viewports.delete(tabId); },
    saveActiveTab: async () => {},
    loadActiveTab: async () => null,
    saveTabLayout: async () => {},
    loadTabLayout: async () => null,
  };
}

describe('encodePcvs / decodePcvs', () => {
  it('round-trips JSON with no blobs', () => {
    const json = '{"version":1,"tabs":[],"items":[],"edges":[],"viewports":{}}';
    const buf = encodePcvs(json, new Map());
    const result = decodePcvs(buf);
    expect(result.json).toBe(json);
    expect(result.blobs.size).toBe(0);
  });

  it('round-trips a single binary blob', () => {
    const data = new Uint8Array([0xDE, 0xAD, 0xBE, 0xEF]).buffer;
    const blobs = new Map<string, ArrayBuffer>([['42:image', data]]);
    const buf = encodePcvs('{}', blobs);
    const result = decodePcvs(buf);
    expect(result.blobs.size).toBe(1);
    expect(new Uint8Array(result.blobs.get('42:image')!)).toEqual(
      new Uint8Array([0xDE, 0xAD, 0xBE, 0xEF])
    );
  });

  it('round-trips multiple blobs', () => {
    const blobs = new Map<string, ArrayBuffer>([
      ['1:image', new Uint8Array([1, 2]).buffer],
      ['2:thumb', new Uint8Array([3, 4, 5]).buffer],
    ]);
    const buf = encodePcvs('{}', blobs);
    const result = decodePcvs(buf);
    expect(result.blobs.size).toBe(2);
    expect(new Uint8Array(result.blobs.get('2:thumb')!)).toEqual(new Uint8Array([3, 4, 5]));
  });

  it('writes little-endian uint32 for JSON length', () => {
    const json = 'ab'; // 2 bytes
    const buf = encodePcvs(json, new Map());
    const view = new DataView(buf);
    expect(view.getUint32(6, true)).toBe(2);  // offset 6 = after magic(4) + version(2)
  });

  it('throws PcvsFormatError on empty buffer', () => {
    expect(() => decodePcvs(new ArrayBuffer(0))).toThrow(PcvsFormatError);
  });

  it('throws PcvsFormatError on wrong magic', () => {
    const buf = new ArrayBuffer(20);
    new Uint8Array(buf).set([0x00, 0x00, 0x00, 0x00]);
    expect(() => decodePcvs(buf)).toThrow(PcvsFormatError);
  });

  it('throws PcvsFormatError on unsupported version', () => {
    const json = '{}';
    const valid = encodePcvs(json, new Map());
    // Patch version to 999
    const view = new DataView(valid);
    view.setUint16(4, 999, true);
    expect(() => decodePcvs(valid)).toThrow(PcvsFormatError);
  });

  it('throws PcvsFormatError on truncated file', () => {
    const json = '{"version":1}';
    const full = encodePcvs(json, new Map());
    const truncated = full.slice(0, 8); // cut off mid-JSON
    expect(() => decodePcvs(truncated)).toThrow(PcvsFormatError);
  });
});

